SELECT EXISTS (SELECT 1 FROM kb_document d JOIN kb_space s ON s.id = d.space_id
WHERE d.id = #{documentId} AND d.status NOT IN ('deleted', 'archived') AND s.archived = FALSE
    AND d.security_level <= #{clearance} AND (


            d.space_id IN #{s}

        FALSE


        OR EXISTS (SELECT 1 FROM kb_document_acl a WHERE a.doc_id = d.id AND a.permission = #{permission}
            AND #{permission} IN ('view', 'download', 'edit') AND a.principal_key IN
            #{k})
    ))
